<script setup>
import {ref,computed,watch,onMounted} from 'vue';import {Head,Link,useForm,router,usePage} from '@inertiajs/vue3';import axios from 'axios';import SubjectPicker from '../Components/SubjectPicker.vue';import StudySheet from '../Components/StudySheet.vue';import Errors from '../Components/Errors.vue';import {message,date} from '../art';
const props=defineProps({catalog:Object,decks:Array}),page=usePage(),setup=ref(null),step=ref(1),search=ref(''),cardCount=ref(20),preview=ref(null),error=ref(''),busy=ref(false),fingerprint=ref('');
const form=useForm({title:'',subjects:[...props.catalog.subjects],topics:[],topic_scope:'all',difficulty:'All',range_start:1,range_end:20,selected_ids:[]});
const topicId=t=>t.subject+'\u001f'+t.topic;
const topics=computed(()=>props.catalog.topics.filter(t=>form.subjects.includes(t.subject)));
const visibleTopics=computed(()=>topics.value.filter(t=>(t.subject+' '+t.topic).toLowerCase().includes(search.value.toLowerCase())));
const validTopics=computed(()=>form.topic_scope==='all'||form.topics.length>0);
const key=()=>JSON.stringify([form.subjects,form.topics,form.topic_scope,form.difficulty,form.range_start,form.range_end]);
const stale=computed(()=>fingerprint.value!==key());
watch(()=>form.subjects.slice(),()=>form.topics=form.topics.filter(t=>form.subjects.includes(t.split('\u001f')[0])));
async function find(){
 if(busy.value)return;busy.value=true;error.value='';const requested=key();
 try{const r=await axios.post('/flashcards/preview',form.data());if(requested!==key())return;
 preview.value=r.data;form.selected_ids=r.data.questions.map(q=>q.id);fingerprint.value=requested;
 if(!preview.value.questions.length)error.value='No questions in this range. Change your selection.';
 }catch(e){error.value=message(e)}finally{busy.value=false}
}
async function next(){if(step.value===1){step.value=2;return}step.value=3;await find()}
async function count(value){cardCount.value=value;form.range_start=1;form.range_end=value;await find()}
async function start(){if(stale.value){await find();return}if(!form.selected_ids.length)return;if(!form.title.trim())form.title=(form.subjects.length===1?form.subjects[0]:'My Memory Maki')+' · '+form.selected_ids.length+(form.selected_ids.length===1?' card':' cards');form.post('/flashcards/decks')}
function quick(pool){busy.value=true;router.post('/flashcards/quick',{pool,subjects:form.subjects},{onFinish:()=>busy.value=false})}
function open(){step.value=1;error.value='';setup.value.open()}
onMounted(()=>{if(new URL(page.url,'http://local').searchParams.has('new')||!props.decks.length)open()});
</script><template><Head title="Memory Maki"/><div class="page-title compact-title"><h1>Memory Maki</h1><button class="primary" @click="open">New deck</button></div>
<section class="panel"><h2>Quick practice</h2><details><summary>Subjects · {{form.subjects.length}} selected</summary><SubjectPicker :subjects="catalog.subjects" v-model="form.subjects"/></details><div class="choice-buttons spaced"><button :disabled="busy||!form.subjects.length" @click="quick('missed')">Missed questions</button><button :disabled="busy||!form.subjects.length" @click="quick('low')">Low confidence</button><button :disabled="busy||!form.subjects.length" @click="quick('bookmarks')">Saved questions</button></div></section>
<section class="panel"><h2>Saved decks</h2><p v-if="!decks.length">Your decks will appear here.</p><div v-for="d in decks" :key="d.id" class="saved-deck row spaced"><div><strong>{{d.title}}</strong><p>{{d.items_count}} cards · {{d.confident_count}} rated 5 · {{date(d.updated_at)}}</p></div><Link :href="'/flashcards/decks/'+d.id" class="button">{{d.session_finished_at?'Open':'Resume'}}</Link></div></section>
<StudySheet ref="setup" title="New deck" :panel-key="step" :busy="busy||form.processing" class="deck-setup"><template #intro><ol class="setup-steps" aria-label="Deck setup"><li v-for="(label,i) in ['Subjects','Topics','Cards']" :key="label" :aria-current="step===i+1?'step':undefined" :class="{current:step===i+1}">{{i+1}} {{label}}</li></ol></template>
<SubjectPicker v-if="step===1" :subjects="catalog.subjects" v-model="form.subjects"/>
<div v-if="step===2"><div class="segmented"><button :aria-pressed="form.topic_scope==='all'" :class="{selected:form.topic_scope==='all'}" @click="form.topic_scope='all';form.topics=[]">All topics</button><button :aria-pressed="form.topic_scope==='custom'" :class="{selected:form.topic_scope==='custom'}" @click="form.topic_scope='custom'">Choose topics</button></div><template v-if="form.topic_scope==='custom'"><label>Search topics<input type="search" v-model="search"></label><div class="row"><span>{{form.topics.length}} selected</span><div><button class="plain" @click="form.topics=topics.map(topicId)">All</button><button class="plain" @click="form.topics=[]">Clear</button></div></div><div class="setup-topics"><label v-for="t in visibleTopics" :key="topicId(t)" class="check"><input type="checkbox" v-model="form.topics" :value="topicId(t)"><span>{{t.topic}}<small>{{t.subject}} · {{t.count}} questions</small></span></label><p v-if="!visibleTopics.length">No matching topics.</p></div><p v-if="!validTopics" class="muted">Choose at least one topic.</p></template><p v-else>{{topics.length}} topics across {{form.subjects.length}} {{form.subjects.length===1?'subject':'subjects'}}.</p></div>
<div v-if="step===3"><h3>How many cards?</h3><div class="card-presets"><button v-for="n in [10,20,50,100]" :key="n" :class="{selected:cardCount===n}" :aria-pressed="cardCount===n" :disabled="busy" @click="count(n)">{{n}}</button></div><p role="status">{{busy?'Loading questions…':preview?form.selected_ids.length+' selected · '+preview.total+' available':''}}</p><details class="advanced-deck"><summary>Advanced options</summary><label>Deck name (optional)<input v-model="form.title" maxlength="150"></label><label>Difficulty<select v-model="form.difficulty"><option>All</option><option>Easy</option><option>Average</option><option>Difficult</option></select></label><div class="form-grid"><label>First question<input type="number" min="1" v-model.number="form.range_start"></label><label>Last question<input type="number" :min="form.range_start" :max="Number(form.range_start)+499" v-model.number="form.range_end"></label></div><p class="muted">Up to 500 cards, in bank order.</p><button :disabled="busy" @click="find">Update selection</button><details v-if="preview&&!stale"><summary>Choose exact questions · {{form.selected_ids.length}}</summary><div class="row"><button class="plain" @click="form.selected_ids=preview.questions.map(q=>q.id)">All</button><button class="plain" @click="form.selected_ids=[]">Clear</button></div><div class="deck-question-list"><label v-for="q in preview.questions" :key="q.id" class="check"><input type="checkbox" v-model="form.selected_ids" :value="q.id"><span><small>{{q.id}} · {{q.topic}}</small>{{q.stem}}</span></label></div></details></details></div>
<Errors :errors="form.errors"/><p v-if="error" class="notice error" role="alert">{{error}}</p>
<template #actions><button :disabled="step===1||busy||form.processing" @click="step--">Back</button><span class="setup-count">{{form.subjects.length}} {{form.subjects.length===1?'subject':'subjects'}}</span><button v-if="step<3" class="primary" :disabled="busy||!form.subjects.length||(step===2&&!validTopics)" @click="next">Next</button><button v-else class="primary" :disabled="busy||form.processing||(!stale&&!form.selected_ids.length)" @click="start">{{form.processing?'Starting…':stale?'Update selection':'Start '+form.selected_ids.length+(form.selected_ids.length===1?' card':' cards')}}</button></template>
</StudySheet></template>
